ea:PaperBasedTest owl:disjointWith ea:ComputerBasedTest .

ea:PracticalTest
    a owl:Class ;
    rdfs:label "Practical Test"@en ;
    rdfs:subClassOf ea:Test .

ea:OralTest
    a owl:Class ;
    rdfs:label "Oral Test"@en ;
    rdfs:subClassOf ea:Test .

ea:Quiz
    a owl:Class ;
    rdfs:label "Quiz"@en ;
